"""74suited, double-board pineapple for the Pittsburgh competition."""
import base64
import zlib
import random

import eval7
from poker_agent_sdk import Action, Agent as BaseAgent

RANKS = "23456789TJQKA"
DECK = [r + s for r in RANKS for s in "cdhs"]
CARD = {name: eval7.Card(name) for name in DECK}
INDEX = {name: i for i, name in enumerate(DECK)}
# Fixed, independent deck orders. Filtering out visible and discarded cards
# gives runouts without replacement. This table holds no gameplay history.
def build_orders():
    rng = random.Random(265801)
    return [rng.sample(DECK, 24) for _ in range(256)]

ORDERS = build_orders()


def board_equities(state, opponents):
    boards = state.variant["boards"]
    street = len(boards[0])
    holes = state.cards
    dead = set(holes) | set(boards[0]) | set(boards[1]) | set(state.variant.get("discarded", ()))
    public = [[CARD[c] for c in board] for board in boards]
    pairs = [[CARD[c] for j, c in enumerate(holes) if j != i] for i in range(3)] if len(holes) == 3 else [[CARD[c] for c in holes]]
    wins = [[0.0, 0.0] for _ in pairs]
    # Two actual opponents for multiway pots. Beyond that use a modest
    # additional multiway discount in the wagering policy.
    rivals = min(2, opponents)
    offset = (sum(INDEX[c] * 7 for c in holes) + sum(INDEX[c] for c in boards[0])) % 256
    trials = (48 if state.phase == "discard" else 24) if len(pairs) == 3 else 36
    missing = 5 - street
    for trial in range(trials):
        order = ORDERS[(offset + trial * 13) % 256]
        needed = 2 * missing + 3 * rivals
        sample = []
        for name in order:
            if name not in dead:
                sample.append(CARD[name])
                if len(sample) == needed:
                    break
        for side in range(2):
            board = public[side] + sample[side * missing:(side + 1) * missing]
            ranks = []
            for rival in range(rivals):
                ix = 2 * missing + rival * 3
                a, b, c = sample[ix:ix+3]
                ranking = eval7.evaluate(board + [a, b])
                # Approximate selection from three cards. An opponent cannot
                # independently retain the perfect pair for both boards.
                if (trial + rival + side) % 2 == 0:
                    ranking = max(ranking, eval7.evaluate(board + [a, c]), eval7.evaluate(board + [b, c]))
                ranks.append(ranking)
            strongest = max(ranks)
            for j, pair in enumerate(pairs):
                ours = eval7.evaluate(board + pair)
                if ours > strongest:
                    wins[j][side] += 1
                elif ours == strongest:
                    wins[j][side] += 1 / (1 + ranks.count(strongest))
    totals = [sum(w) / (2 * trials) for w in wins]
    best = max(range(len(pairs)), key=lambda i: totals[i])
    return best, totals[best], min(wins[best]) / trials


def raise_sized(state, target):
    legal = state.can("raise")
    if legal:
        return Action.raise_to(max(legal.min_amount, min(legal.max_amount, int(target))))
    return Action.check() if state.can("check") else Action.call()



