def preflop_key(cards):
    # Sort descending by rank. Among tied ranks maximize the suit-match bits.
    a,b,c=sorted((INDEX[x] for x in cards),reverse=True)
    ra,rb,rc=a//4,b//4,c//4
    ab,ac,bc=a%4==b%4,a%4==c%4,b%4==c%4
    if ra==rb and bc>ac:
        ac,bc=bc,ac
    if rb==rc and ac>ab:
        ab,ac=ac,ab
    return (((ra*13+rb)*13+rc)*8)+4*ab+2*ac+bc
def eligible_pot(state, me):
    # Chips bet above our entire stack for this street cannot be won by us.
    cap = me.bet + me.stack
    return max(1, state.pot - sum(max(0, s.bet - cap) for s in state.seats))

def hero_payout(stacks, hero, payouts, remaining):
    chips = stacks[hero]
    if not chips:
        return payouts[remaining - 1] if remaining <= len(payouts) else 0.
    total = sum(stacks)
    p1 = chips / total
    p2 = p3 = 0.
    for i, first in enumerate(stacks):
        if i == hero or first <= 0:
            continue
        left = total - first
        p2 += first / total * chips / left
        if len(payouts) >= 3:
            for j, second in enumerate(stacks):
                if j != hero and j != i and second > 0:
                    p3 += first / total * second / left * chips / (left - second)
    return sum(pr * value for pr, value in zip((p1, p2, p3), payouts))


def profitable_call_after_open(state, me, foe, cost, pot, called_share):
    stacks = [s.stack for s in state.seats]
    stacks[foe.seat] += state.pot
    payouts = state.config.payouts
    remaining = state.players_remaining
    folded = hero_payout(stacks, me.seat, payouts, remaining)
    outcomes = []
    for fraction in (0., .5, 1.):
        transfer = int(fraction * (pot + cost)) - cost
        stacks[me.seat] += transfer
        stacks[foe.seat] -= transfer
        outcomes.append(hero_payout(stacks, me.seat, payouts, remaining) - folded)
        stacks[me.seat] -= transfer
        stacks[foe.seat] += transfer
    lose, split, win = outcomes
    q = called_share
    return (1 - q) ** 2 * lose + 2 * q * (1 - q) * split + q ** 2 * win >= .30


def profitable_short_call(state, me, opp, cost, pot, random_eq, opening_eq):
    seats = [s.stack for s in state.seats]
    seats[opp.seat] += state.pot
    payouts = state.config.payouts
    remaining = state.players_remaining
    folded = hero_payout(seats, me.seat, payouts, remaining)
    arm = []
    for share in (0., .5, 1.):
        amount = int(share * (pot + cost)) - cost
        seats[me.seat] += amount
        seats[opp.seat] -= amount
        arm.append(hero_payout(seats, me.seat, payouts, remaining) - folded)
        seats[me.seat] -= amount
        seats[opp.seat] += amount
    lose, split, win = arm
    q = .4 * random_eq + .6 * opening_eq
    adjacent = (1 - 2 * q) * lose + 2 * q * split if q <= .5 else (2 - 2 * q) * split + (2 * q - 1) * win
    value = .45 * adjacent + .55 * ((1 - q) * lose + q * win)
    return value >= .60


def profitable_blind_reshove(state, me, opener, called_share, fold_rate):
    stacks = [seat.stack for seat in state.seats]
    hero = me.seat
    villain = opener.seat
    pot = state.pot
    effective = min(me.stack + me.bet, opener.stack + opener.bet)
    our_cost = effective - me.bet
    their_cost = effective - opener.bet
    stacks[villain] += pot
    payouts = state.config.payouts
    remaining = state.players_remaining
    fold_value = hero_payout(stacks, hero, payouts, remaining)
    def transfer(chips):
        stacks[hero] += chips
        stacks[villain] -= chips
        result = hero_payout(stacks, hero, payouts, remaining) - fold_value
        stacks[hero] -= chips
        stacks[villain] += chips
        return result
    steal = transfer(pot)
    showdown = pot + our_cost + their_cost
    lose = transfer(-our_cost)
    split = transfer(showdown // 2 - our_cost)
    win = transfer(showdown - our_cost)
    q = called_share
    called = (1 - q) ** 2 * lose + 2 * q * (1 - q) * split + q ** 2 * win
    return fold_rate * steal + (1 - fold_rate) * called


def facing_large_raise(state, me, cost, bb, foes, high):
    i = preflop_key(state.cards)*3
    random_eq, opening_eq, premium_eq = (x/250.0 for x in PREFLOP_EQUITIES[i:i+3])
    raises = sum(e.kind == "raise" for e in state.history)
    short = (me.stack + me.bet < 12*bb)
    if raises >= 2:
        equity = .8*premium_eq + .2*opening_eq
    elif short or state.players_remaining <= 3:
        equity = .45*random_eq + .55*opening_eq
    else:
        equity = .45*opening_eq + .55*premium_eq
    committed = sum(s.bet >= min(high,me.bet+cost)*.8 or s.status=="all_in" for s in foes)
    equity *= .80**max(0,committed-1)
    pot = eligible_pot(state,me)
    price = cost/(pot+cost)
    if (state.players_remaining >= 3 and len(foes) == 1 and raises >= 2
            and (foes[0].stack == 0 or cost == me.stack) and price >= .35
            and min(me.bet + me.stack, foes[0].bet + foes[0].stack) >= 28 * bb
            and random_eq <= .73 and premium_eq <= .67):
        return Action.fold()
    risk = .03 + .055*min(1,cost/max(1,me.stack))
    paid = sum(p > 0 for p in state.config.payouts)
    if state.players_remaining==paid+1 and cost>me.stack*.35:
        risk += .06
    if equity < price + risk:
        if (len(foes) == 1 and 3 <= state.players_remaining <= 8 and raises == 1
                and len(state.config.payouts) <= 3 and (foes[0].stack == 0 or cost == me.stack)
                and min(me.stack + me.bet, foes[0].stack + foes[0].bet) <= 14 * bb
                and profitable_short_call(state, me, foes[0], cost, pot, random_eq, opening_eq)):
            return Action.call()
        return Action.fold()
    if equity > .63 and me.stack>cost and state.can("raise"):
        return raise_sized(state,me.stack+me.bet if high*3>=me.stack*.65 else high*3)
    return Action.call()


