RIVER_RANGE = random.Random(741041).sample([(pair, 1) for pair in combinations(CARD.values(), 2)], 384)

def river_actions(history):
    for event in reversed(history):
        if event.kind == "board":
            break
        yield event


def priced_river_share(state, me, foe, cost, price, pot_bb):
    hold = [CARD[x] for x in state.cards]
    strength = []
    types = []
    for board in state.variant["boards"]:
        public = [CARD[x] for x in board]
        strength.append(eval7.py_hand_vs_range_exact(hold, RIVER_RANGE, public))
        types.append(eval7.evaluate(hold + public) >> 24)
    aggression = [0, 0, 0]
    street = 0
    raised = checked = 0
    for event in state.history:
        if event.kind == "board" and event.amount == 1:
            street += 1
        elif event.kind == "raise":
            if street < 3 and event.seat == foe.seat:
                aggression[street] = 1
            if street == 3 and event.seat == me.seat:
                raised = 1
        elif street == 3 and event.kind == "check" and event.seat == me.seat:
            checked = 1
    features = [min(strength), max(strength), price, cost/max(1,me.stack),
                log1p(pot_bb), *aggression, raised, checked, min(types), max(types)]
    return tree_estimate(features, RIVER_BASE, RIVER_TREES)


