def street_call_value(state, me, foe, share, weaker, street, price, cost, pot_bb, paid):
    current = 0
    aggression = [0, 0, 0]
    prior_hero = checked = reraised = False
    for event in state.history:
        if event.kind == "board" and event.amount == 1:
            current += 1
        elif event.kind == "raise":
            if event.seat == foe.seat and current < 3:
                aggression[current] = 1
            if event.seat == me.seat:
                if current == 0:
                    prior_hero = True
                if current == street - 2:
                    reraised = True
        elif current == street - 2 and event.kind == "check" and event.seat == me.seat:
            checked = True
    if reraised:
        return 0.0
    count = state.players_remaining
    x = [share, weaker, street-2, price, cost / max(1, me.stack), log1p(pot_bb),
         count, int(count==paid+1), int(checked), 0, aggression[0], int(prior_hero),
         aggression[1] if street == 4 else 0, share-price]
    return tree_estimate(x, STREET_BASE, STREET_TREES)


