OPEN_BASE, OPEN_TREES = json.loads(zlib.decompress(base64.b85decode(OPEN_BLOB)))


def estimate_open_points(state, tier_start, stack_bb, opponents, bb):
    hi, mid, lo = sorted((INDEX[c] // 4 for c in state.cards), reverse=True)
    pair_rank = hi if hi == mid else mid if mid == lo else -1
    suits = [x[1] for x in state.cards]
    high_suit = max(state.cards, key=lambda c: INDEX[c] // 4)[1]
    # The seat after the button was the small blind and the button acted last
    # postflop, independent of folds before this decision.
    count = state.players_remaining
    button = state.button
    clockwise = sorted((s.seat for s in state.seats if s.status != "busted"),
                       key=lambda s: (s - button - 1) % len(state.seats))
    pos = 3 if state.seat == button else 2 if state.seat == clockwise[-2] else 1 if state.seat == clockwise[-3] else 0
    equity = PREFLOP_EQUITIES
    eff = min((s.stack + s.bet for s in state.seats if s.seat != state.seat and s.status in ("active", "all_in")), default=0) / bb
    if eff < 8:
        return 1.0
    x = [equity[tier_start+1]/250, equity[tier_start]/250, equity[tier_start+2]/250,
         hi, mid, lo, int(pair_rank >= 0), pair_rank, len(set(suits)), int(suits.count(high_suit) >= 2),
         hi-mid, mid-lo, hi-lo, int(hi == 12), int(hi >= 10 and mid >= 8), opponents,
         count, int(pos==0), int(pos==1), int(pos==2), int(pos==3),
         log1p(stack_bb), log1p(eff), log1p(state.hand_number)]
    return tree_estimate(x, OPEN_BASE, OPEN_TREES)


def tree_estimate(features, estimate, trees):
    for tree in trees:
        node = tree[0]
        while not node[5]:
            node = tree[node[2] if features[node[0]] <= node[1] else node[3]]
        estimate += node[4]
    return estimate




def record_response(data, offset, is_fold):
    if data[offset] == 255:
        data[offset] //= 2
        data[offset + 1] //= 2
    data[offset] += 1
    data[offset + 1] += is_fold


def track_responses(state, memory):
    # Per seat: preflop first response, then first response to a flop lead.
    seats = len(state.seats)
    size = 7 + 6 * seats
    data = bytearray(memory) if len(memory) == size else bytearray(size)
    anchor = 3 + 4 * seats
    alive = data[anchor] | data[anchor + 1] << 8
    if not alive:
        alive = (1 << seats) - 1
    hu_phase, opener = data[anchor + 2], data[anchor + 3]
    mode = data[0]
    acted = data[1] | (data[2] << 8)
    for event in state.events:
        kind = event.kind
        if kind == "stack":
            if event.amount == 0:
                alive &= ~(1 << event.seat)
        elif kind == "hand":
            hu_phase = 1 if alive.bit_count() == 2 else 0
        elif kind == "board":
            hu_phase = 0
        elif hu_phase and kind in ("raise", "fold", "check", "call"):
            if hu_phase == 1 and kind == "raise":
                hu_phase, opener = 2, event.seat
            elif hu_phase == 2 and event.seat != opener:
                record_response(data, anchor + 4 + 2 * event.seat, kind == "raise")
                hu_phase = 0
            else:
                hu_phase = 0
        if kind == "hand":
            mode, acted = 1, 0
        elif kind == "board":
            if event.amount == 1:
                mode = 3 if len(event.cards) == 3 else 0
        elif mode in (1, 2) and kind in ("fold", "call", "raise", "check"):
            seat = event.seat
            bit = 1 << seat
            if mode == 2 and not acted & bit:
                record_response(data, 3 + 2 * seat, kind == "fold")
            acted |= bit
            if kind == "raise":
                mode = 2
        elif mode == 3:
            if kind == "check":
                mode = 0
            elif kind == "raise":
                mode = 4
        elif mode == 4 and kind in ("fold", "call", "raise"):
            record_response(data, 3 + 2 * seats + 2 * event.seat, kind == "fold")
            mode = 0
    data[0], data[1], data[2] = mode, acted & 255, acted >> 8
    data[anchor:anchor + 4] = bytes((alive & 255, alive >> 8, hu_phase, opener))
    return bytes(data)


import math
import struct

NAMES = DECK
TO_ID = INDEX
EC = [CARD[c] for c in NAMES]
PAIR_INDEX = ((1,2),(0,2),(0,1))
BIT = [1 << (i//4) for i in range(52)]
STRAIGHTS = [0x100F]+[31<<i for i in range(9)]
DRAW = []
for mask in range(8192):
    outs=0
    for straight in STRAIGHTS:
        missing=straight & ~mask
        if missing and missing & (missing-1)==0:
            outs|=missing
    DRAW.append(outs)

def board_info(b):
    mask=0
    suited=[0]*4
    for c in b:
        mask |= BIT[c]
        suited[c%4] |= BIT[c]
    return mask,suited,[c//4 for c in sorted(b,reverse=True)],[EC[c] for c in b]

def features(b, other, hold, locked, rivals, pot):
    mask,suits,ranks,board=b
    a,bc=sorted(hold,reverse=True)
    ar,br=a//4,bc//4
    sr,ss=a%4,bc%4
    combo=mask|BIT[a]|BIT[bc]
    strength=eval7.evaluate(board+[EC[a],EC[bc]])
    sa=suits[sr]|BIT[a]
    sb=suits[ss]|BIT[bc]
    if sr==ss:
        sa=sb=sa|sb
    flush=max(sa.bit_count(),sb.bit_count())
    drawrank=max(ar if sa.bit_count()==flush else -1,br if sb.bit_count()==flush else -1)
    outs=DRAW[combo]
    clean=outs & ~DRAW[mask]
    cat=strength>>24
    high=strength>>16&15
    kicker=strength>>12&15
    second=strength>>8&15
    return [cat,high,kicker,second,ar,br,int(ar==br),int(sr==ss),
        flush,drawrank,outs.bit_count(),clean.bit_count(),int(bool(BIT[a]&mask)),int(bool(BIT[bc]&mask)),
        mask.bit_count(),ranks[0],ranks[1],ranks[-1],max(m.bit_count() for m in suits),DRAW[mask].bit_count(),
        (mask>>(high+1)).bit_count(),(mask>>(ar+1)).bit_count(),(mask>>(br+1)).bit_count(),
        int(bool(other[0]&BIT[a])),int(bool(other[0]&BIT[bc])),
        locked,min(4,rivals),struct.unpack("f", struct.pack("f", math.log1p(pot)))[0]]


def add_features(board,other,keep,drop):
 a,b=sorted(keep,reverse=True); mask,suits,ranks,pub=board
 oa=other[0];om=mask|BIT[a]|BIT[b]
 ev=eval7.evaluate(pub);fav=eval7.evaluate(pub+[EC[a],EC[b]])
 first=fav>>16&15;second=fav>>12&15;third=fav>>8&15
 masks=[(suits[i],(suits[i]|(BIT[a] if a%4==i else 0)|(BIT[b] if b%4==i else 0))) for i in range(4)]
 draw=DRAW[om] & ~DRAW[mask]
 blocked=other[2]+[drop//4]
 made= fav>>24
 return [ev>>24,ev>>16&15,ev>>12&15,ranks.count(first),ranks.count(second),
    (BIT[drop]&mask)!=0,drop//4,len(set(other[2])&{a//4,b//4}),
    sum((1<<v)&draw!=0 for v in blocked), int(bool(BIT[drop]&draw)),
    max((s|o).bit_count() for s,o in zip(suits,other[1])),
    max((13*after.bit_count()+12-other[1][i].bit_count()-int(drop%4==i)) for i,(before,after) in enumerate(masks)),
    sum(suits[i].bit_count()==3 for i in range(4)),sum((1<<v)&om!=0 for v in other[2]),
    int(first==a//4),int(first==b//4),int(second==a//4),int(second==b//4),
    (mask>>(second+1)).bit_count(),sum(v>first for v in other[2]),sum(v>second for v in other[2]),
    max((r for r in range(13) if draw & (1<<r)),default=-1)]


