def learned_discard(state, rivals):
    holes = [TO_ID[c] for c in state.cards]
    info = [board_info([TO_ID[c] for c in board]) for board in state.variant['boards']]
    locked = int(sum(s.status == 'active' and s.stack > 0 for s in state.seats) <= 1)
    pot_bb = state.pot / max(1, state.blinds.big_blind)
    trace = [0] * 5
    street = 0
    for e in state.history:
        if e.kind == 'board' and e.amount == 1:
            street += 1
        elif e.kind == 'raise' and street < 2:
            trace[street] += 1
            if e.seat != state.seat:
                trace[2 + street] += 1
            elif street == 1:
                trace[4] += 1
    scores = [0.] * 3
    for j, board in enumerate(info):
        other = info[1-j]
        for k, (a, b) in enumerate(PAIR_INDEX):
            keep = [holes[a], holes[b]]
            fs = features(board, other, keep, locked, rivals, pot_bb)
            fs.extend(add_features(board, other, keep, holes[k]))
            fs.extend(trace)
            scores[k] += discard_pair_score(fs)
    return max(range(3), key=scores.__getitem__)


def checked_through_flop(history):
    street = 0
    for event in history:
        if event.kind == "board" and event.amount == 1:
            street += 1
            if street == 2:
                return True
        elif street == 1 and event.kind == "raise":
            return False
    return False

def opponent_raised_our_flop_lead(state, opponent):
    # This line contains exactly two flop bets. Opponent first raised preflop,
    # then responded to our lead without any intervening caller or flop check.
    last_preflop_raiser = None
    flop = False
    bets = []
    for event in state.history:
        if event.kind == "board":
            flop = True
        elif not flop:
            if event.kind == "raise":
                last_preflop_raiser = event.seat
        elif event.kind in ("call", "check"):
            return False
        elif event.kind == "raise":
            bets.append(event.seat)
    return last_preflop_raiser == opponent and bets == [state.seat, opponent]

def steal_from_tight_blinds(state, memory, me, foes, bb, opening_eq):
    if (me.bet or state.players_remaining < 3 or state.players_remaining > 5
            or len(foes) != 2 or me.stack < 12 * bb
            or state.seat != state.button or opening_eq < .34):
        return False
    fold_read = 1.0
    for foe in foes:
        if foe.stack < 12 * bb:
            return False
        at = 3 + 2 * foe.seat
        fold_read *= (5 + memory[at + 1]) / (8 + memory[at])
    return fold_read >= .74


def update_free_bet_counts(state, memory):
    # Separate per-seat counts for heads-up flop free bets, conditional
    # on both players being eligible for live betting. Fixed-size table memory.
    n = len(state.seats)
    size = 6 + 2*n
    data = bytearray(memory) if len(memory) == size else bytearray(size)
    live = int.from_bytes(data[:2], 'little')
    alive = int.from_bytes(data[2:4], 'little') or ((1 << n)-1)
    street, raised = data[4], data[5]
    for e in state.events:
        k = e.kind
        if k == 'stack':
            if not e.amount: alive &= ~(1 << e.seat)
        elif k == 'hand':
            live, street, raised = alive, 0, 0
        elif k == 'board' and e.amount == 1:
            street, raised = street+1, 0
        elif k == 'fold':
            live &= ~(1 << e.seat)
        elif k in ('check','raise'):
            eligible = street == 1 and not raised and live.bit_count() == 2
            if eligible:
                offset = 6+2*e.seat
                if data[offset] == 255:
                    data[offset] //= 2
                    data[offset+1] //= 2
                data[offset] += 1
                data[offset+1] += k == 'raise'
            if k == 'raise':
                raised = 1 if eligible else 2
    data[:2] = live.to_bytes(2,'little')
    data[2:4] = alive.to_bytes(2,'little')
    data[4], data[5] = street, raised
    return bytes(data)


def prior_free_bet_read(memory, n, street, opponent):
    if memory[5] != 1:
        return 0
    offset = 6+2*opponent
    seen, bets = memory[offset], memory[offset+1]
    # The current first bet has been added by the event tracker. Remove it
    # before applying the prequential thresholds learned from prior decisions.
    seen -= 1
    bets -= 1
    if seen < 3:
        return 0
    if (3+bets) / (7+seen) <= .32:
        return -1
    if (3+bets) / (7+seen) >= .55:
        return 1
    return 0

