def frequency_adjusted_fold(state, memory, opponent, street, price, cost, stack, share, points, paid):
    if street != 3 or not (-.65 <= points < .30 and state.players_remaining >= 3):
        return False
    # Baseline points == 0 also means our own earlier raise. Exclude that unit.
    if any(e.kind == "raise" and e.seat == state.seat for e in river_actions(state.history)):
        return False
    n = len(state.seats)
    anchor = 7 + 6 * n
    if prior_free_bet_read(memory[anchor:], n, street, opponent) >= 0:
        return False
    coarse = (street-2, price >= .18, price >= .29, round((share-price)*5))
    cell = coarse + (points < -.65, points < 0., points < 1.2,
                     state.players_remaining == paid+1, cost/max(1,stack) > .65)
    return cell in NEGATIVE_STREET_CELLS if cell in KNOWN_STREET_CELLS else coarse in NEGATIVE_STREET_GROUPS


class Agent(BaseAgent):
    def act(self, state, memory):
        n = len(state.seats)
        anchor = 7 + 6 * n
        base = track_responses(state, memory[:anchor])
        extra = update_free_bet_counts(state, memory[anchor:])
        memory = base + extra
        return self.choose(state, memory), memory

    def choose(self, state, memory):
        me = next(s for s in state.seats if s.seat == state.seat)
        foes = [s for s in state.seats if s.seat != me.seat and s.status in ("active", "all_in")]
        opponents = max(1, len(foes))
        bb = max(1, state.blinds.big_blind)
        cost = min(me.stack, state.to_call)
        checking = state.can("check") is not None
        late = state.seat == state.button
        stack_bb = (me.stack + me.bet) / bb
        if state.phase == "discard":
            index = learned_discard(state, opponents)
            return Action("discard", cards=(index,))
        if not state.board:
            start = preflop_key(state.cards) * 3
            opening_eq = PREFLOP_EQUITIES[start + 1] / 250
            high = max(s.bet for s in state.seats)
            count = state.players_remaining
            button = state.seat == state.button
            big_blind = any(e.kind == "blind" and e.seat == me.seat and e.amount == bb for e in state.history)
            late_position = button or (not me.bet and opponents <= 3)
            short = stack_bb < 11
            if ((count in (3, 4) or 5 <= count <= 8 and opening_eq < .43)
                    and big_blind and opponents == 1 and me.bet == bb
                    and 1.8 * bb <= high <= 3.2 * bb and .30 <= opening_eq < .55
                    and state.can("raise") and len(state.config.payouts) <= 3):
                opener = foes[0]
                effective = min(me.stack + me.bet, opener.stack + opener.bet)
                late_opener = opener.seat == state.button or any(
                    e.kind == "blind" and e.seat == opener.seat for e in state.history)
                if (late_opener and opener.stack > 0 and 5 * bb <= effective <= 25 * bb
                        and sum(e.kind == "raise" for e in state.history) == 1
                        and not any(e.kind == "call" for e in state.history)):
                    called_share = PREFLOP_EQUITIES[start + 2] / 250
                    fold_rate = .70 if count == 3 else .73
                    required_gain = .20 if count in (3, 4) else .40
                    if profitable_blind_reshove(state, me, opener, called_share, fold_rate) >= required_gain:
                        return raise_sized(state, effective)
            if (count == 2 and big_blind and opponents == 1 and me.bet == bb
                    and 1.8 * bb <= high <= 2.8 * bb and 0.31 <= opening_eq < 0.55
                    and state.can("raise") and sum(e.kind == "raise" for e in state.history) == 1):
                effective = min(me.stack + me.bet, foes[0].stack + foes[0].bet) / bb
                if 5 <= effective <= 24:
                    # Model the chips won on a fold and versus a top-decile calling range.
                    # A premium over folding also accounts for the value of a flat call.
                    fold_rate = 0.72 if effective < 10 else 0.78 if effective < 16 else 0.76 if effective < 21 else 0.70
                    called_share = PREFLOP_EQUITIES[start + 2] / 250
                    called_bb = 2 * effective * called_share - (effective - 1)
                    shove_bb = fold_rate * (high / bb + 1) + (1 - fold_rate) * called_bb
                    if shove_bb >= 0.70:
                        return raise_sized(state, int(round(effective * bb)))
            if (count == 2 and opponents == 1 and cost and high > bb
                    and (foes[0].stack == 0 or cost == me.stack)
                    and min(me.stack + me.bet, foes[0].stack + foes[0].bet) <= 18 * bb):
                # Both paid places are fixed heads up. Extra tournament points are linear in chips.
                num_raises = sum(e.kind == "raise" for e in state.history)
                pot_odds = cost / (eligible_pot(state, me) + cost)
                random_eq = PREFLOP_EQUITIES[start] / 250
                if (num_raises == 1 and 0.72 * random_eq + 0.28 * opening_eq >= pot_odds + 0.010
                        or num_raises >= 2 and opening_eq >= pot_odds + 0.010):
                    return Action.call()
            if (count >= 4 and opponents == 1 and high >= 7 * bb
                    and cost and cost < 0.25 * me.stack and opening_eq < 0.60
                    and min(me.bet + me.stack, foes[0].bet + foes[0].stack) >= 40 * bb):
                # Deep in a re-raised pot, marginal opens struggled to realize their equity.
                previous_raises = [e.seat for e in state.history if e.kind == "raise"]
                if previous_raises == [me.seat, foes[0].seat] and foes[0].stack > 0:
                    return Action.fold()
            if (3 <= count <= 8 and opponents == 1 and cost and high > bb
                    and len(state.config.payouts) <= 3 and (foes[0].stack == 0 or cost == me.stack)
                    and .28 <= opening_eq <= .70
                    and 4 * bb <= min(me.stack + me.bet, foes[0].stack + foes[0].bet) <= 22 * bb):
                bets = [e for e in state.history if e.kind == "raise"]
                early_blind = (min(me.stack + me.bet, foes[0].stack + foes[0].bet) <= 15 * bb
                               and any(e.kind == "blind" and e.seat == foes[0].seat for e in state.history))
                if ((count <= 4 or early_blind) and len(bets) == 2 and bets[0].seat == me.seat
                        and 1.75 * bb <= bets[0].amount <= 3.5 * bb
                        and not any(e.kind == "call" for e in state.history[:state.history.index(bets[0])])):
                    premium_eq = PREFLOP_EQUITIES[start + 2] / 250
                    if profitable_call_after_open(state, me, foes[0], cost, eligible_pot(state, me),
                                                  .55 * opening_eq + .45 * premium_eq):
                        return Action.call()
            if (big_blind and count >= 3 and opponents == 1 and me.bet > bb and high > me.bet
                    and .35 <= opening_eq < .50):
                effective = min(me.stack + me.bet, foes[0].stack + foes[0].bet) / bb
                if effective > 25 and (count <= 4 and effective <= 60 or count >= 5 and effective < 35):
                    bets = [event for event in state.history if event.kind == "raise"]
                    if (len(bets) == 3 and [e.seat for e in bets] == [foes[0].seat, me.seat, foes[0].seat]
                            and 1.8 * bb <= bets[0].amount <= 3.2 * bb and bets[1].amount == 3 * bets[0].amount
                            and (foes[0].seat == state.button or any(e.kind == "blind" and e.seat == foes[0].seat for e in state.history))
                            and not any(e.kind == "call" for e in state.history)):
                        return Action.fold()
            if cost and high > bb and (cost >= 0.40 * me.stack or high >= 8 * bb):
                return facing_large_raise(state, me, cost, bb, foes, high)
            if high <= bb:
                threshold = 0.457
                if count <= 2:
                    threshold = 0.314 if button else 0.405
                elif late_position:
                    threshold = 0.398
                elif count <= 4:
                    threshold = 0.415
                limpers = sum(e.kind == "call" for e in state.history)
                if limpers:
                    threshold += min(0.045, limpers * 0.015)
                if big_blind and checking:
                    threshold = max(threshold, 0.475)
                if short and not limpers:
                    threshold -= 0.025
                if (count >= 3 and opponents == 1 and not big_blind and me.bet > 0
                        and foes[0].bet == bb and me.bet < bb and not limpers
                        and min(me.stack, foes[0].stack) >= 12 * bb
                        and opening_eq < threshold - 0.035):
                    # Frequent prior folds to an opening raise identify overfolding blinds.
                    offset = 3 + 2 * foes[0].seat
                    if 10 * (3 + memory[offset + 1]) >= 7 * (5 + memory[offset]):
                        return raise_sized(state, 2.6 * bb)
                if (count == 2 and button and not limpers and not short
                        and opening_eq < 0.43 and min(stack_bb, (foes[0].bet + foes[0].stack) / bb) >= 5):
                    # Weak button opens struggle against blinds that repeatedly re-raise.
                    offset = 7 + 4 * len(state.seats) + 2 * foes[0].seat
                    opportunities, reraises = memory[offset], memory[offset + 1]
                    if opportunities >= 3 and 2 * reraises >= opportunities:
                        return Action.fold()
                if (not limpers and opening_eq < threshold
                        and steal_from_tight_blinds(state, memory, me, foes, bb, opening_eq)):
                    return raise_sized(state, 2.2 * bb)
                if opening_eq >= threshold:
                    if (not limpers and not me.bet and count >= 4 and stack_bb >= 11
                            and estimate_open_points(state, start, stack_bb, opponents, bb) < -.05):
                        return Action.fold()
                    # Around the previous 11 BB boundary, medium-strength hands earned
                    # more by taking the fold equity at once. Preserve the opening range.
                    extend_shove = (not limpers and count >= 3 and 11 <= stack_bb < 17
                                    and .46 <= opening_eq < .55 and foes
                                    and min(s.stack + s.bet for s in foes) >= 10 * bb)
                    size = me.bet + me.stack if short or extend_shove else (2.6 + 0.9 * limpers) * bb
                    return raise_sized(state, size)
                if checking:
                    return Action.check()
                if me.bet > 0 and cost <= 0.5*bb and opening_eq >= threshold-0.035:
                    if (count == 4 and opponents == 1 and not limpers and not big_blind
                            and .38 <= opening_eq < .414 and min(stack_bb, (foes[0].stack + foes[0].bet) / bb) > 11):
                        return raise_sized(state, 2.6 * bb)
                    return Action.call()
                return Action.fold()
            if checking:
                return Action.check()
            raises = sum(e.kind == "raise" for e in state.history)
            # The practice field charged our weakest cold calls heavily. A second
            # raise, players behind us, and high prices each narrow our range.
            repop = 0.585 if count > 3 else 0.550
            if (big_blind and count >= 5 and opponents == 1 and raises == 1
                    and 1.8 * bb <= high <= 3.5 * bb and 0.40 <= opening_eq < 0.55
                    and min(me.bet + me.stack, foes[0].bet + foes[0].stack) >= 35 * bb
                    and not any(e.kind == "call" for e in state.history)):
                opener = foes[0].seat
                if opener == state.button or any(
                        e.kind == "blind" and e.seat == opener for e in state.history):
                    return raise_sized(state, 3 * high)
            if raises <= 1 and opening_eq >= repop:
                size = me.bet + me.stack if stack_bb < 16 else high * (3.2 if not button else 2.8)
                return raise_sized(state, size)
            price = cost / (eligible_pot(state, me) + cost)
            floor = 0.485 if count > 3 else 0.452
            if button:
                floor -= 0.012
            if big_blind and raises == 1:
                floor -= 0.042 if high <= 3.2 * bb else 0.014
            if count == 2:
                floor -= 0.048
            if raises >= 2:
                floor += 0.055
            floor += max(0.0, price-0.30)*0.35
            if (big_blind and count >= 3 and opponents == 1 and raises == 1
                    and .35 <= opening_eq < min(.55, floor) and 1.8 * bb <= high <= 3.2 * bb
                    and foes[0].status == "active" and not any(e.kind == "call" for e in state.history)):
                effective = min(me.stack + me.bet, foes[0].stack + foes[0].bet) / bb
                opener = foes[0].seat
                if (effective > 25 and (count <= 4 and effective <= 60 or count >= 5 and effective < 35)
                        and (opener == state.button or any(e.kind == "blind" and e.seat == opener for e in state.history))):
                    return raise_sized(state, 3 * high)
            return (Action.call() if opening_eq >= floor else Action.fold())

        _, share, weaker_side = board_equities(state, opponents)
        if opponents > 2:
            share *= 1 / (1 + 0.09 * (opponents - 2))
        pot = eligible_pot(state, me)
        price = cost / (pot + cost)
        risk = 0.045 + 0.058 * (cost / max(1, me.stack))
        payouts = state.config.payouts
        paid = sum(p > 0 for p in payouts)
        if state.players_remaining == paid + 1 and cost > me.stack * 0.35:
            risk += 0.06
        # A sizeable first river bet represents a much stronger range than
        # the unconditioned random holdings in board_equities.
        street = len(state.board)
        if cost and (street in (3, 4) and price >= 0.18 or street == 5 and opponents == 1 and price >= 0.29):
            we_raised = False
            for event in reversed(state.history):
                if event.kind == "board":
                    break
                if event.kind == "raise" and event.seat == state.seat:
                    we_raised = True
                    break
            if not we_raised:
                if street == 5:
                    risk += 0.18
                elif opponents == 1:
                    risk += 0.18 if price >= 0.29 else 0.14
                else:
                    risk += 0.12
        value_cut = (0.65 if opponents == 1 else 0.55) + (0.07 if cost else 0)
        can_steal = checking and late and opponents == 1 and share > 0.47 and len(state.board) < 5
        if (street == 3 and checking and not late and opponents == 1 and share > 0.47
                and foes[0].status == "active" and min(me.stack, foes[0].stack) >= .72 * pot
                and state.history and state.history[-1].kind == "check"):
            can_steal = True
        if (street == 3 and checking and opponents == 1 and state.players_remaining >= 3
                and .60 <= share < .65 and foes[0].status == "active"
                and min(me.stack, foes[0].stack) >= .72 * pot
                and state.history and state.history[-1].kind == "board"):
            last_opener = next((event.seat for event in reversed(state.history)
                                if event.kind == "raise"), None)
            if last_opener == me.seat:
                can_steal = True
        if (street == 3 and checking and opponents == 1 and .30 <= share < .55
                and foes[0].status == "active" and min(me.stack, foes[0].stack) >= pot
                and state.history and state.history[-1].kind == "board"):
            offset = 3 + 2 * len(state.seats) + 2 * foes[0].seat
            # Two earlier folds from two opportunities qualify a responder.
            if 2 * (1 + memory[offset + 1]) >= 4 + memory[offset]:
                can_steal = True
        if (street == 4 and opponents == 1 and checking and share < .65
                and foes[0].status == "active" and state.players_remaining >= 3
                and min(me.stack, foes[0].stack) >= .72 * pot and state.history):
            turn_action = state.history[-1].kind
            delayed_bet = (turn_action == "check" and not late and share > .47
                           or turn_action == "board" and share >= .60)
            if delayed_bet and checked_through_flop(state.history):
                can_steal = True
        if share >= value_cut or can_steal:
            fraction = 0.72 if share > 0.79 and weaker_side > 0.38 else 0.48
            target = me.bet + cost + fraction * (pot + cost)
            return raise_sized(state, target)
        if checking:
            return Action.check()
        if share < price + risk:
            return Action.fold()
        if (street == 3 and opponents == 1 and state.players_remaining >= 3
                and share < .72 and price >= .25
                and min(me.stack - cost, foes[0].stack) >= .20 * (pot + cost)
                and opponent_raised_our_flop_lead(state, foes[0].seat)):
            return Action.fold()
        if street in (3, 4) and opponents == 1:
            call_points = street_call_value(state, me, foes[0], share, weaker_side, street, price, cost, pot/bb, paid)
            if call_points < -0.65:
                return Action.fold()
            if frequency_adjusted_fold(state, memory, foes[0].seat, street, price, cost,
                                       me.stack, share, call_points, paid):
                return Action.fold()
        if street == 5 and opponents == 1 and not any(
                e.kind == "raise" and e.seat == me.seat for e in river_actions(state.history)):
            estimated = priced_river_share(state, me, foes[0], cost, price, pot/bb)
            if estimated < price - 0.025:
                return Action.fold()
        return Action.call()
